const MASS = {H:1, C:12, N:14, O:16, Na:23, Cl:35, Fe:56, Cu:64};
const S = readline();
const reg = /([A-Z][a-z]?)(\d*)/g;
let total = 0;
let m;
while ((m = reg.exec(S)) !== null) {
    if (m[0] === '')
        break;
    total += MASS[m[1]] * (m[2] ? parseInt(m[2]) : 1);
}
console.log(total);
